/* cppi::d11a8228a1f2aef896946b22d742de690f99b9c84c5ccee3f357e546a5ed3e6f */
SELECT COUNT(*) FROM (SELECT DISTINCT sec.abor_security_name_id, sec.abor_instrument_type_id, sec.abor_security_group_name, sec.abor_security_id, sec.abor_security_number, sec.isin_id, sec.sedol_id, sec.cusip_id, sec.bloomberg_unique_id, sec.cadis_id, sec.cpp_ex_id, sec.cppib_sec_id, sec.abor_exchange_id, hld.abor_maturity_date, CURRENT_DATE AS EXTRACT_DATE, sec.created_date AS CREATED_DATE FROM reference.scd_securities sec RIGHT OUTER JOIN Holdings.scd_holdings_main hld ON sec.cppib_sec_id = hld.cppib_sec_id WHERE sec.abor_instrument_type_id > ' ' AND sec.abor_instrument_type_id NOT IN ('ALM', 'Bank account', 'Cash bucket', 'Index security') AND sec.abor_security_id NOT LIKE ('XXX%') AND (TRY_CAST(hld.abor_maturity_date AS date) > CURRENT_DATE - INTERVAL '5' day OR (hld.abor_maturity_date IS NULL)) AND sec.bloomberg_unique_id NOT LIKE ('%NULL%') AND sec.bloomberg_unique_id NOT LIKE ('SS%') AND sec.cadis_id IS NOT NULL
) dbvrcnt

/* cppi::d11a8228a1f2aef896946b22d742de690f99b9c84c5ccee3f357e546a5ed3e6f */
SELECT COUNT(*) FROM (SELECT DISTINCT sec.abor_security_name_id, sec.abor_instrument_type_id, sec.abor_security_group_name, sec.abor_security_id, sec.abor_security_number, sec.isin_id, sec.sedol_id, sec.cusip_id, sec.bloomberg_unique_id, sec.cadis_id, sec.cpp_ex_id, sec.cppib_sec_id, sec.abor_exchange_id, hld.abor_maturity_date, CURRENT_DATE AS EXTRACT_DATE, sec.created_date AS CREATED_DATE FROM reference.scd_securities sec RIGHT OUTER JOIN Holdings.scd_holdings_main hld ON sec.cppib_sec_id = hld.cppib_sec_id WHERE sec.abor_instrument_type_id > ' ' AND sec.abor_instrument_type_id NOT IN ('ALM', 'Bank account', 'Cash bucket', 'Index security') AND sec.abor_security_id NOT LIKE ('XXX%') AND (TRY_CAST(hld.abor_maturity_date AS date) > CURRENT_DATE - INTERVAL '5' day OR (hld.abor_maturity_date IS NULL)) AND sec.bloomberg_unique_id NOT LIKE ('%NULL%') AND sec.bloomberg_unique_id NOT LIKE ('SS%') AND sec.cadis_id IS NOT NULL
) dbvrcnt

