/* QuickSight */
SELECT ds.* FROM ( select *,
DENSE_RANK() OVER (ORDER BY business_date DESC) AS date_rank
from risk_prod.rmv_position
where business_date = (select max(business_date) from risk_prod.rmv_position) ) ds LIMIT 0

