/* cppi::d9f697660c29e510bbc2fef1fbad86f6e3e29cb10e6923ea24745f7ccb0685cd */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-06' and business_date <= date '2025-06-06' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::5dcee2a34e1b088622af926c7e2369b67d63de57e379fb1267455dfaa45ca0ba */
